func FetchAsync(ctx context.Context, url string) <-chan Result {
    ch := make(chan Result, 1)            // buffered: one send, no receiver needed
    go func() {
        v, err := fetch(ctx, url)         // work happens off the caller's goroutine
        ch <- Result{Value: v, Err: err}  // completion delivered exactly once
    }()
    return ch                             // caller continues immediately
}
